head.script:
scwin.screenId = "uldmgt50008";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "if_noForms", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "noForms" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("noForms"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "noForms" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("noForms")))).length === 0)); } }, { id: "tr_20", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "noForms" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("noForms"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "noForms" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("noForms")))).length === 0)); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 29
 * @param boxId
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function (boxId) {
    // 채우지 못한 자리를 모은다(동작은 계속 — 화면은 종전과 같다).
    const genSkip = [];
    let genCleared = 0;
    const genFills = [{ genId: "c_foreach_22", entity: "dlt_noForms", countIds: [], cells: [{ childId: "__rc0", fn: function (v, i) { return String(v("formCd")); } }, { childId: "__rc1", fn: function (v, i) { return String(v("formVer")); } }] }];
    const gf = genFills;
    for (let g = 0; g < gf.length; g++) {
        const f = gf[g];
        if (boxId && f.entity !== boxId) { continue; }
        const gen = $c.util.getComponent(f.genId);
        const ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { genSkip.push({ gen: f.genId, box: f.entity, why: !gen ? 'no-generator' : 'no-box' }); continue; }
        const n = ds.getRowCount();
        if (!n) { genSkip.push({ gen: f.genId, box: f.entity, why: 'empty-box' }); continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        //   단, 상자를 지정해 «다시 그리라» 고 부른 경우(데이터가 새로 담긴 때)는 비우고 다시 채운다.
        if (gen.getLength && gen.getLength() > 0) {
            if (!boxId) { continue; }
            const had = gen.getLength();
            while (gen.getLength() > 0) { gen.removeChild(); }
            genCleared += had;
        }
        let row = 0;
        const cell = function (col) { const v = ds.getCellData(row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                const ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                const cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
            // 행 조건 — 마지막 행에만 보이는 자리.
            if (f.rowConds) {
                for (let rc = 0; rc < f.rowConds.length; rc++) {
                    const rn = gen.getChild(i, f.rowConds[rc].childId);
                    if (!rn) { continue; }
                    const show = (f.rowConds[rc].kind === 'last') ? (i === n - 1) : true;
                    if (rn.setStyle) { rn.setStyle('display', show ? '' : 'none'); }
                }
            }
        }
    }
    if (genSkip.length) {
        // 우리 계측이 읽는 자리 — 화면 동작에는 영향이 없다.
        scwin.genFillSkipped = genSkip;
    }
    if (genCleared) { scwin.genFillCleared = (scwin.genFillCleared || 0) + genCleared; }
};

// dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_rowCopy
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_rowCopy = async function () {
    const rows = [{ childId: "__rb2", fn: function () { return String(String(((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : "")(dma_pageContext.get("htmlContent")))); } }];
    let copied = 0;
    for (let i = 0; i < rows.length; i++) {
        const it = rows[i];
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { console.warn("[sdd] 행 복사 대상 부재: " + it.childId); continue; }
        try {
            const v = it.fn();
            if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); copied++; }
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); }
    }
    return copied;
};

// [A] 초기 목록 미해결 — uldmgt50008: 열자마자 목록을 채울 근거가 없다(진입 URL 0 · 자기 목록 tx 0 · 화면 자신의 액션 URL 도 못 가름)


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_fillGen();
        await scwin.init_rowCopy();
        await scwin.init_conds();
    } catch (e) {
        $c.exception.handleError(e, { context: 'uldmgt50008.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.slc_lang_onchange
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.slc_lang_onchange = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin slc_lang_onchange — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.showForm(selfVar)
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50008.slc_lang_onchange' }); }
};

/**
 * @event
 * @name scwin.img_18_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.img_18_onclick = function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin img_18_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        scwin.printForm()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'uldmgt50008.img_18_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////



///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.showForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.showForm = function (obj) {
    /* sdd-asis-lifecycle:begin fn_ShowForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.setPageFrameSrc($c.win.getFrame(), '/formprocslist/formprocslist.xml') + dma_pageContext.get("formCd") + "&formVer=" + dma_pageContext.get("formVer") + "" + "&lang=" + obj.value;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.printForm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.printForm = function () {
    /* sdd-asis-lifecycle:begin printForm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    $c.win.popupPrint();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.copyXpath
 * @author Inswave
 * @date 2026. 09. 29
 * @param obj
 * @returns
 * @hidden N
*/
scwin.copyXpath = function (obj) {
    /* sdd-asis-lifecycle:begin copyXpath — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    navigator.clipboard.setData("Text", "/xbrli:xbrl" + obj.xpath);
    /* sdd-asis-lifecycle:end */
};
